"""One exception manifest, four real authorization objects; no provider emulation."""
import copy
import datetime

KINDS = ('role', 'network', 'database', 'session')


def instant(value):
    if not isinstance(value, str):
        raise ValueError('explicit timezone-aware timestamp required')
    parsed = datetime.datetime.fromisoformat(value)
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError('explicit timezone-aware timestamp required')
    return parsed.astimezone(datetime.timezone.utc)


def text(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError('nonempty actual identity, owner and reason required')
    return value.strip()


def bind(ticket, objects):
    if not isinstance(ticket, dict) or not isinstance(objects, dict) or set(objects) != set(KINDS):
        raise ValueError('complete four-object original mapping required')
    if not {'ticket_id', 'approval_id', 'owner', 'reason', 'issued_at', 'expires_at'} <= set(ticket) or type(ticket.get('closed', False)) is not bool:
        raise ValueError('complete typed original approval record required')
    issued = instant(ticket['issued_at'])
    expires = instant(ticket['expires_at'])
    if expires <= issued:
        raise ValueError('finite approved deadline must follow issue time')
    profile = ticket.get('timing_profile', 'production')
    if profile not in ('production', 'mechanism_trial'):
        raise ValueError('explicit approved timing profile required')
    duration = (expires - issued).total_seconds()
    if profile == 'production' and duration != 604800:
        raise ValueError('original production policy is exactly seven days')
    if profile == 'mechanism_trial' and duration > 60:
        raise ValueError('mechanism trial is explicitly short, not seven days elapsed')
    items = {}
    for kind in KINDS:
        row = objects[kind]
        if not isinstance(row, dict):
            raise ValueError('actual provider object mapping required')
        if not {'resource', 'principal', 'scope', 'baseline', 'initial_locations'} <= set(row):
            raise ValueError('complete actual location and original baseline required')
        resource = text(row['resource'])
        principal = text(row['principal'])
        scope = row['scope']
        baseline = row['baseline']
        locations = row['initial_locations']
        if not isinstance(scope, list) or not scope or not all(isinstance(item, str) and item for item in scope) or len(set(scope)) != len(scope):
            raise ValueError('explicit finite unique approved scope required')
        if not isinstance(baseline, list) or not all(isinstance(item, str) and item for item in baseline):
            raise ValueError('original baseline must be independently retained')
        if not isinstance(locations, list) or not locations or not all(isinstance(item, str) and item for item in locations):
            raise ValueError('actual original backend locations must be retained')
        items[kind] = {'resource': resource, 'principal': principal, 'scope': list(scope), 'baseline': list(baseline), 'initial_locations': list(locations)}
    return {'ticket_id': text(ticket['ticket_id']), 'approval_id': text(ticket['approval_id']),
            'owner': text(ticket['owner']), 'reason': text(ticket['reason']),
            'issued_at': issued.isoformat(), 'expires_at': expires.isoformat(),
            'objects': items, 'production_policy_duration_seconds': 604800, 'timing_profile': profile,
            'extension_count': 0, 'max_extensions': 1, 'max_extension_seconds': duration,
            'status': 'active', 'ticket_closed': bool(ticket.get('closed', False))}


def approval(record, change, *, recovery=False):
    if not isinstance(change, dict):
        raise ValueError('fresh approval required')
    if not {'approval_id', 'reason', 'approver', 'expires_at'} <= set(change):
        raise ValueError('complete fresh approval reason and finite deadline required')
    identifier = text(change['approval_id'])
    if identifier == record['approval_id']:
        raise ValueError('original authorization is not fresh extension or recovery approval')
    reason, approver = text(change['reason']), text(change['approver'])
    expires = instant(change['expires_at'])
    now = datetime.datetime.now(datetime.timezone.utc)
    if expires <= now:
        raise ValueError('new finite future deadline required')
    scopes = change.get('scopes')
    if recovery:
        maximum = 604800 if record['timing_profile'] == 'production' else 60
        if expires > now + datetime.timedelta(seconds=maximum):
            raise ValueError('fresh minimal recovery must have a bounded approved window')
        if not isinstance(scopes, dict) or set(scopes) != set(KINDS):
            raise ValueError('fresh four-object minimal recovery scope required')
        for kind in KINDS:
            values = scopes[kind]
            if not isinstance(values, list) or not all(isinstance(item, str) and item for item in values) or len(set(values)) != len(values):
                raise ValueError('explicit finite minimal recovery scope required')
            if not set(values) <= set(record['objects'][kind]['scope']):
                raise ValueError('recovery cannot enlarge the original approved scope')
        if not any(scopes.values()):
            raise ValueError('recovery requires at least one explicitly approved object scope')
    else:
        if record['extension_count'] >= record['max_extensions']:
            raise ValueError('a single exception cannot renew indefinitely')
        previous = instant(record['expires_at'])
        if expires <= previous or (expires - previous).total_seconds() > record['max_extension_seconds']:
            raise ValueError('extension requires a later deadline within the bounded original window')
    return {'approval_id': identifier, 'reason': reason, 'approver': approver,
            'expires_at': expires.isoformat(), 'scopes': copy.deepcopy(scopes) if recovery else None}

