"""Bounded direct calls to the four provided real provider adapters."""
import datetime
from exception_record import KINDS, approval, instant


def withdraw(record, providers):
    now = datetime.datetime.now(datetime.timezone.utc)
    if now < instant(record['expires_at']):
        return {'due': False, 'attempted': [], 'errors': [], 'observations': observe(record, providers)}
    attempted, errors = [], []
    for kind in KINDS:
        attempted.append(kind)
        try:
            providers.revoke(kind, record['objects'][kind])
            if kind == 'database':
                providers.close_existing_database_sessions(record['objects'][kind])
        except (OSError, TimeoutError, RuntimeError) as error:
            errors.append({'kind': kind, 'error_class': type(error).__name__, 'message': 'actual provider withdrawal not confirmed'})
    return {'due': True, 'attempted': attempted, 'errors': errors, 'observations': observe(record, providers)}


def observe(record, providers):
    observations = {}
    for kind in KINDS:
        try:
            observations[kind] = providers.inspect(kind, record['objects'][kind])
        except (OSError, TimeoutError, RuntimeError) as error:
            observations[kind] = {'resource': record['objects'][kind]['resource'], 'principal': record['objects'][kind]['principal'],
                                  'policy_present': None, 'allowed': None, 'baseline_preserved': None,
                                  'error_class': type(error).__name__, 'message': 'actual policy and target refusal remain unverified'}
    return observations


def recover(record, change, providers):
    approved = approval(record, change, recovery=True)
    attempted, errors = [], []
    for kind in KINDS:
        if not approved['scopes'][kind]:
            continue
        attempted.append(kind)
        try:
            providers.restore(kind, record['objects'][kind], approved['scopes'][kind])
        except (OSError, TimeoutError, RuntimeError) as error:
            errors.append({'kind': kind, 'error_class': type(error).__name__, 'message': 'actual approved minimal recovery not confirmed'})
    return {'approval': approved, 'attempted': attempted, 'errors': errors, 'observations': observe(record, providers)}

